<script>function addVariant(){const f=new FormData();f.append('_token','{{csrf_token()}}');f.append('sku',document.getElementById('v_sku').value);f.append('attributes',document.getElementById('v_attr').value||'{}');f.append('price',document.getElementById('v_price').value);f.append('wholesale_price',document.getElementById('v_wholesale').value);f.append('group_price',document.getElementById('v_group').value);f.append('stock_qty',document.getElementById('v_stock').value);fetch('{{route('admin.products.variations.store',$item->id)}}',{method:'POST',body:f}).then(async r=>{if(!r.ok)alert('Variant could not be saved.');else location.reload();});}</script>
